_cgb65_dispatch() {
  case "$1" in
    0)
      cp evil /etc/hosts
      return $?
      ;;
    1|2) _cgb65_dispatch "$(( $1 - 1 ))" ;;
    *) return 2 ;;
  esac
}
_cgb65_dispatch 2

